#include "PreRTS.h"
#include "Common/INI.h"

// ?parseSecondsToMillis@INI@@SAXPAV1@PAX1PBX@Z
void INI::parseSecondsToMillis(INI *ini, void * /*instance*/, void *store, const void * /*userData*/)
{
	const char *token = ini->getNextToken();
	*(UnsignedInt *)store = (UnsignedInt)(INI::scanReal(token) * 1000.0f);
}
